import os
import base64

PROJECT_NAME = "HomeHub_Pro"

FILES = {
    "main.py": "",
    "modules/__init__.py": "",
    "modules/database.py": "",
    "modules/expenses.py": "",
    "modules/todo.py": "",
    "modules/calories.py": ""
}

def generate_project():
    print(f"[*] Начало сборки проекта '{PROJECT_NAME}'...")
    os.makedirs(PROJECT_NAME, exist_ok=True)
    
    for relative_path, b64_content in FILES.items():
        full_path = os.path.join(PROJECT_NAME, relative_path)
        dir_name = os.path.dirname(full_path)
        if dir_name:
            os.makedirs(dir_name, exist_ok=True)
            
        if b64_content:
            content = base64.b64decode(b64_content.encode('utf-8')).decode('utf-8')
        else:
            content = ""
            
        with open(full_path, "w", encoding="utf-8") as f:
            f.write(content)
        print(f"[+] Сгенерирован: {full_path}")
        
    print(f"\n[🎉] Успешно! Перейдите в '{PROJECT_NAME}' и запустите 'main.py'.")

if __name__ == "__main__":
    generate_project()
